def fuse_roots(dsk, keys):
    """ Fuse roots of a HighLevelGraph.
    """
    if isinstance(dsk, HighLevelGraph):
        layers = dsk.layers
        dependencies = dsk.dependencies
    else:
        layers = {k: {k} for k in dsk}
        dependencies = {k: set() for k in dsk}

    keys = set(keys)

    for key in keys & set(layers):
        deps = dependencies[key]
        if (
            len(layers[key]) == 1
            and len(deps) == 1
            and not any(dependencies[dep] for dep in deps)  # no need to fuse if 0 or 1
            and all(len(dependencies[dep]) == 1 for dep in deps)
        ):
            new = layers[deps.pop()].copy()
            new[key] = layers[key][key]
            dsk = dsk.copy()
            dsk.layers = dsk.layers.copy()
            dsk.layers[key] = new
            dsk.dependencies = dsk.dependencies.copy()
            dsk.dependencies[key] = set()

    return dsk
