def set_initial_conditions_from(self, solution, inplace=True, with_passive_separators=True, check_impact=True):
    """
    Set initial conditions from the given solution object.

    This is useful for multi-stage models, where the initial conditions are
    set from the solution of a previous stage.

    Parameters
    ----------
    solution : :class:`pybamm.Solution`
        The solution to use to set the initial conditions.
    inplace: bool
        If True, modify the model in place. Otherwise, return a new model.
    with_passive_separators: bool
        If True, keep the passive separators (e.g. "Separator" in the
        variables dictionary) ...
    check_impact: bool
        If True, check that the model has been changed...

    Returns
    -------
    :class:`pybamm.BaseModel`
        The model with the initial conditions set.
    """
    if inplace:
        model = self
    else:
        model = self.new_copy()

